# Target cube and expected fixed-width record length
sCubeName = '<TargetCube>';
nExpectedLength = <RecordLength>;

# Suspend cube logging during the load, restore it in Epilog
nOldLogChanges = CUBEGETLOGCHANGES(sCubeName);
CUBESETLOGCHANGES(sCubeName, 0);

# Counters for the run summary
nRecordsRead = 0;
nRecordsLoaded = 0;
nRecordsRejected = 0;
