# DATA

nRecordsRead = nRecordsRead + 1;

# Reject any line that is not the expected fixed-width length
nLineLength = LONG(V1);
IF(nLineLength <> nExpectedLength);
   nRecordsRejected = nRecordsRejected + 1;
   ItemSkip;
ENDIF;

# Cut fields out of the wide record by start position and length
sField1 = TRIM(SUBST(V1, <Field1Start>, <Field1Length>));
sField2 = TRIM(SUBST(V1, <Field2Start>, <Field2Length>));
sAmount = TRIM(SUBST(V1, <AmountStart>, <AmountLength>));
nAmount = NUMBR(sAmount);

# Reject rows whose dimension elements do not exist
IF(DIMIX('<Dim1>', sField1) = 0 % DIMIX('<Dim2>', sField2) = 0);
   nRecordsRejected = nRecordsRejected + 1;
   ItemSkip;
ENDIF;

CellPutN(nAmount, sCubeName, sField1, sField2);
nRecordsLoaded = nRecordsLoaded + 1;
